package com.bank.flink.time;

import java.math.BigDecimal;

// Carries THREE timestamps so we can compare semantics:
//  eventTime      - when the swipe actually happened (on the receipt)
//  ingestionTime  - when the Flink source first saw it
//  processingTime - when the operator handled it (clerk's clock)
class TransactionEvent {
    private final String accountId;
    private final BigDecimal amount;
    private final long eventTimeMillis;
    private final long ingestionTimeMillis;
    private final long processingTimeMillis;

    TransactionEvent(String accountId, BigDecimal amount,
                     long eventTimeMillis, long ingestionTimeMillis, long processingTimeMillis) {
        this.accountId = accountId;
        this.amount = amount;
        this.eventTimeMillis = eventTimeMillis;
        this.ingestionTimeMillis = ingestionTimeMillis;
        this.processingTimeMillis = processingTimeMillis;
    }

    String getAccountId() { return accountId; }
    BigDecimal getAmount() { return amount; }
    long getEventTimeMillis() { return eventTimeMillis; }
    long getIngestionTimeMillis() { return ingestionTimeMillis; }
    long getProcessingTimeMillis() { return processingTimeMillis; }
}
