package com.bank.flink.time;

// Floors a timestamp to its one-minute window start. The ONLY difference
// between the three semantics is WHICH timestamp we feed in here.
class TimeSemanticsBucketer {
    private final long windowSizeMillis;

    TimeSemanticsBucketer(long windowSizeMillis) {
        this.windowSizeMillis = windowSizeMillis;
    }

    long bucketByEventTime(TransactionEvent e) {
        return floor(e.getEventTimeMillis());
    }

    long bucketByIngestionTime(TransactionEvent e) {
        return floor(e.getIngestionTimeMillis());
    }

    long bucketByProcessingTime(TransactionEvent e) {
        return floor(e.getProcessingTimeMillis());
    }

    private long floor(long ts) {
        return ts - (ts % windowSizeMillis);
    }
}
