package com.bank.flink.time;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// The AUDITABLE report. It MUST use event time so each transaction lands
// in the business minute when the money actually moved.
class SettlementReporter {
    private static final Logger log = Logger.getLogger(SettlementReporter.class.getName());

    private final TimeSemanticsBucketer bucketer;
    private final Map<Long, BigDecimal> totalsByMinute = new HashMap<>();

    SettlementReporter(TimeSemanticsBucketer bucketer) {
        this.bucketer = bucketer;
    }

    void record(TransactionEvent e) {
        long bucket = bucketer.bucketByEventTime(e);
        totalsByMinute.merge(bucket, e.getAmount(), BigDecimal::add);
        log.info(() -> "SETTLEMENT (event-time) " + e.getAccountId()
                + " amount " + e.getAmount() + " -> minute " + bucket);
    }

    Map<Long, BigDecimal> getTotalsByMinute() { return totalsByMinute; }
}
