package com.bank.flink.time;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// The LIVE health dashboard. It uses processing time because it only cares
// about how many transactions the servers handled per wall-clock minute.
class ThroughputMonitor {
    private static final Logger log = Logger.getLogger(ThroughputMonitor.class.getName());

    private final TimeSemanticsBucketer bucketer;
    private final Map<Long, Integer> countsByMinute = new HashMap<>();

    ThroughputMonitor(TimeSemanticsBucketer bucketer) {
        this.bucketer = bucketer;
    }

    void record(TransactionEvent e) {
        long bucket = bucketer.bucketByProcessingTime(e);
        countsByMinute.merge(bucket, 1, Integer::sum);
        log.info(() -> "THROUGHPUT (processing-time) handled 1 txn -> minute " + bucket);
    }

    Map<Long, Integer> getCountsByMinute() { return countsByMinute; }
}
