package com.bank.flink.time;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: one delayed transaction placed into different minutes by
// event time vs ingestion time vs processing time.
public class TimeSemanticsDemo {
    private static final Logger log = Logger.getLogger(TimeSemanticsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new BankTimeLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        long windowSize = 60_000L;
        TimeSemanticsBucketer bucketer = new TimeSemanticsBucketer(windowSize);
        SettlementReporter settlement = new SettlementReporter(bucketer);
        ThroughputMonitor throughput = new ThroughputMonitor(bucketer);

        // Rajesh's swipe truly happened at 09:59:59 (=59_000ms in our timeline),
        // reached Flink at 10:00:30 (ingestion) and was processed at 10:03:00 (processing).
        TransactionEvent delayed = new TransactionEvent(
                "SAV2001", new BigDecimal("5000.00"),
                59_000,    // event time  -> minute 0 (the 09:59 slot)
                90_000,    // ingestion   -> minute 60000 (the 10:00 slot)
                240_000);  // processing  -> minute 240000 (the 10:03 slot)

        settlement.record(delayed);  // event time -> correct business minute
        throughput.record(delayed);  // processing time -> live minute

        log.info(() -> "Event-time bucket    = " + bucketer.bucketByEventTime(delayed));
        log.info(() -> "Ingestion-time bucket= " + bucketer.bucketByIngestionTime(delayed));
        log.info(() -> "Processing-time bucket= " + bucketer.bucketByProcessingTime(delayed));
    }
}

// ─── Would be in BankTimeLogFormatter.java in a real project ───
class BankTimeLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
